css:
/* A4 sheet. The PDF button obeys Print Settings > PDF Page Size, so keep that on A4. */
@page { size: A4 portrait; margin: 10mm; }
.eims-attendance { direction: rtl; text-align: right; font-family: Tahoma, Arial, sans-serif; font-size: 12px; color: #000; }
.eims-attendance .logo { display: block; margin: 0 auto 4px; max-height: 210px; max-width: 280px; object-fit: contain; }
.eims-attendance .school { text-align: center; font-size: 15px; font-weight: bold; }
.eims-attendance .title { text-align: center; font-size: 14px; font-weight: bold; margin: 2px 0 10px; }
.eims-attendance .meta { display: flex; justify-content: space-between; font-weight: bold; margin-bottom: 4px; }
.eims-attendance table { width: 100%; border-collapse: collapse; table-layout: fixed; }
.eims-attendance th, .eims-attendance td { border: 1px solid #444; padding: 4px 6px; height: 24px; text-align: right; overflow-wrap: anywhere; }
.eims-attendance th { background: #eee !important; font-weight: bold; }
.eims-attendance thead { display: table-header-group; }
.eims-attendance tr { page-break-inside: avoid; }
.eims-attendance .c-num { width: 34px; text-align: center; }
.eims-attendance .c-status { width: 70px; text-align: center; }
.eims-attendance .c-notes { width: 30%; }
.eims-attendance .tally { width: auto; table-layout: auto; margin-top: 8px; }
.eims-attendance .tally th, .eims-attendance .tally td { white-space: nowrap; padding: 4px 10px; }
.eims-attendance .tally td { text-align: center; }
.eims-attendance .notes { margin-top: 8px; }
.eims-attendance .sign { display: flex; justify-content: space-between; margin-top: 24px; font-weight: bold; }
